const data=JSON.parse(fs.readFileSync('/root/DATA/metadata/employee.json','utf8'));
// data is object keyed by eid
function findByName(name){
  const res=[];
  for (const [eid, info] of Object.entries(data)){
    if (!info) continue;
    const full=(info.name || [info.first_name, info.last_name].filter(Boolean).join(' ')).trim();
    if (full.toLowerCase()===name.toLowerCase()) res.push({eid, ...info, full});
  }
  return res;
}
for (const name of ['Julia Smith','Ian Jones','George Jones','Hannah Miller','George Miller','Charlie Smith','Julia Garcia','Julia Davis']){
  const res=findByName(name);
  console.log(name, res);
}
